int cdrom_get_status(struct cdrom_device_info *cdi, unsigned long arg) {
    if (!(cdi->flags & CDO_STATUS))
        return -EINVAL;

    if (!arg)
        return -EINVAL;

    if (arg == CDROM_CURRENT_STATUS)
        return cdi->ops->get_status(cdi, 0);

    if (arg == CDROM_SELECT_SPEED)
        return cdi->ops->get_status(cdi, 1);

    return -EINVAL;
}

int get_cdrom_drive_status(struct cdrom_device_info *cdi, unsigned long arg) {
    if (!(cdi->capability & CDC_DRIVE_STATUS)) {
        return -EINVAL;
    }

    if (arg > CDROM_LAST_STATUS) {
        return -EINVAL;
    }

    return cdi->ops->drive_status(cdi, arg);
}

int get_cdrom_drive_status(struct cdrom_device_info *cdi, unsigned long arg) {
    if (!(cdi->capabilities & CDC_STATUS) || !cdi->get_status)
        return -EINVAL;

    if (!(*cdi->can_be_accessed)(cdi))
        return -ENODEV;

    return cdi->get_status(cdi, arg);
}

int cdrom_get_status(struct cdrom_device_info *cdi, unsigned long arg) {
    if (!(cdi->flags & CDO_STAT))
        return -EINVAL;

    if (arg >= CDROM_MAX_SLOT)
        return -EINVAL;

    if (cdi->ops->get_status)
        return cdi->ops->get_status(cdi, arg);

    return -ENOSYS;
}

int get_cdrom_drive_status(struct cdrom_device_info *cdi, unsigned long arg) {
    if (!(cdi->capabilities & CDC_DRIVE_STATUS)) {
        return -EINVAL;
    }

    if (!can_perform_operation(cdi, arg)) {
        return -EPERM;
    }

    return cdi->ops->get_drive_status(cdi, arg);
}
